    57→func newExplainCmd() *cobra.Command {
    58→	var sessionFlag string
    59→	var commitFlag string
    60→	var checkpointFlag string
    61→	var noPagerFlag bool
    62→	var verboseFlag bool
    63→	var fullFlag bool
    64→
    65→	cmd := &cobra.Command{
    66→		Use:   "explain",
    67→		Short: "Explain a session, commit, or checkpoint",
    68→		Long: `Explain provides human-readable context about sessions, commits, and checkpoints.
    69→
    70→Use this command to understand what happened during agent-driven development,
    71→either for self-review or to understand a teammate's work.
    72→
    73→By default, explains the current session. Use flags to explain a specific
    74→session, commit, or checkpoint.
    75→
    76→Output verbosity levels (for --checkpoint):
    77→  Default:   Summary view (ID, session, timestamp, tokens, intent)
    78→  --verbose: + prompts and files touched
    79→  --full:    + complete transcript
    80→
    81→Only one of --session, --commit, or --checkpoint can be specified at a time.`,
    82→		RunE: func(cmd *cobra.Command, _ []string) error {
    83→			// Check if Entire is disabled
    84→			if checkDisabledGuard(cmd.OutOrStdout()) {
    85→				return nil
    86→			}
    87→
    88→			return runExplain(cmd.OutOrStdout(), sessionFlag, commitFlag, checkpointFlag, noPagerFlag, verboseFlag, fullFlag)
    89→		},
    90→	}
    91→
    92→	cmd.Flags().StringVar(&sessionFlag, "session", "", "Explain a specific session (ID or prefix)")
    93→	cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref)")
    94→	cmd.Flags().StringVar(&checkpointFlag, "checkpoint", "", "Explain a specific checkpoint (ID or prefix)")
    95→	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
    96→	cmd.Flags().BoolVarP(&verboseFlag, "verbose", "v", false, "Show prompts, files, and session IDs")
    97→	cmd.Flags().BoolVar(&fullFlag, "full", false, "Show complete transcript")
    98→
    99→	return cmd
   100→}
