   102→// runExplain routes to the appropriate explain function based on flags.
   103→func runExplain(w io.Writer, sessionID, commitRef, checkpointID string, noPager, verbose, full bool) error {
   104→	// Count mutually exclusive flags
   105→	flagCount := 0
   106→	if sessionID != "" {
   107→		flagCount++
   108→	}
   109→	if commitRef != "" {
   110→		flagCount++
   111→	}
   112→	if checkpointID != "" {
   113→		flagCount++
   114→	}
   115→	if flagCount > 1 {
   116→		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
   117→	}
   118→
   119→	// Route to appropriate handler
   120→	if sessionID != "" {
   121→		return runExplainSession(w, sessionID, noPager)
   122→	}
   123→	if commitRef != "" {
   124→		return runExplainCommit(w, commitRef)
   125→	}
   126→	if checkpointID != "" {
   127→		return runExplainCheckpoint(w, checkpointID, noPager, verbose, full)
   128→	}
   129→
   130→	// Default: explain current session
   131→	return runExplainDefault(w, noPager)
   132→}
