   134→// runExplainCheckpoint explains a specific checkpoint.
   135→func runExplainCheckpoint(w io.Writer, checkpointIDPrefix string, noPager, verbose, full bool) error {
   136→	repo, err := openRepository()
   137→	if err != nil {
   138→		return fmt.Errorf("not a git repository: %w", err)
   139→	}
   140→
   141→	store := checkpoint.NewGitStore(repo)
   142→
   143→	// Find checkpoint by prefix
   144→	committed, err := store.ListCommitted(context.Background())
   145→	if err != nil {
   146→		return fmt.Errorf("failed to list checkpoints: %w", err)
   147→	}
   148→
   149→	var fullCheckpointID string
   150→	for _, info := range committed {
   151→		if strings.HasPrefix(info.CheckpointID, checkpointIDPrefix) {
   152→			fullCheckpointID = info.CheckpointID
   153→			break
   154→		}
   155→	}
   156→
   157→	if fullCheckpointID == "" {
   158→		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
   159→	}
   160→
   161→	// Load checkpoint data
   162→	result, err := store.ReadCommitted(context.Background(), fullCheckpointID)
   163→	if err != nil {
   164→		return fmt.Errorf("failed to read checkpoint: %w", err)
   165→	}
   166→
   167→	// Look up the commit message for this checkpoint
   168→	commitMessage := findCommitMessageForCheckpoint(repo, fullCheckpointID)
   169→
   170→	// Format and output
   171→	output := formatCheckpointOutput(result, fullCheckpointID, commitMessage, verbose, full)
   172→
   173→	if noPager {
   174→		fmt.Fprint(w, output)
   175→	} else {
   176→		outputWithPager(w, output)
   177→	}
   178→
   179→	return nil
   180→}
