   182→// findCommitMessageForCheckpoint searches git history for a commit with the
   183→// Entire-Checkpoint trailer matching the given checkpoint ID, and returns
   184→// the first line of the commit message. Returns empty string if not found.
   185→func findCommitMessageForCheckpoint(repo *git.Repository, checkpointID string) string {
   186→	// Get HEAD reference
   187→	head, err := repo.Head()
   188→	if err != nil {
   189→		return ""
   190→	}
   191→
   192→	// Iterate through commit history (limit to recent commits for performance)
   193→	commitIter, err := repo.Log(&git.LogOptions{
   194→		From: head.Hash(),
   195→	})
   196→	if err != nil {
   197→		return ""
   198→	}
   199→	defer commitIter.Close()
   200→
   201→	const maxCommitsToSearch = 500
   202→	count := 0
   203→
   204→	for {
   205→		commit, iterErr := commitIter.Next()
   206→		if iterErr != nil {
   207→			break
   208→		}
   209→		count++
   210→		if count > maxCommitsToSearch {
   211→			break
   212→		}
   213→
   214→		// Check if this commit has our checkpoint ID
   215→		foundID, hasTrailer := paths.ParseCheckpointTrailer(commit.Message)
   216→		if hasTrailer && foundID == checkpointID {
   217→			// Return first line of commit message (without trailing newline)
   218→			firstLine := strings.Split(commit.Message, "\n")[0]
   219→			return strings.TrimSpace(firstLine)
   220→		}
   221→	}
   222→
   223→	return ""
   224→}
