   226→// formatCheckpointOutput formats checkpoint data based on verbosity level.
   227→// Default: Summary (ID, session, timestamp, tokens, intent)
   228→// Verbose: + prompts, files, commit message
   229→// Full: + complete transcript
   230→func formatCheckpointOutput(result *checkpoint.ReadCommittedResult, checkpointID, commitMessage string, verbose, full bool) string {
   231→	var sb strings.Builder
   232→	meta := result.Metadata
   233→
   234→	// Header - always shown
   235→	shortID := checkpointID
   236→	if len(shortID) > 12 {
   237→		shortID = shortID[:12]
   238→	}
   239→	fmt.Fprintf(&sb, "Checkpoint: %s\n", shortID)
   240→	fmt.Fprintf(&sb, "Session: %s\n", meta.SessionID)
   241→	fmt.Fprintf(&sb, "Created: %s\n", meta.CreatedAt.Format("2006-01-02 15:04:05"))
   242→
   243→	// Token usage
   244→	if meta.TokenUsage != nil {
   245→		totalTokens := meta.TokenUsage.InputTokens + meta.TokenUsage.CacheCreationTokens +
   246→			meta.TokenUsage.CacheReadTokens + meta.TokenUsage.OutputTokens
   247→		fmt.Fprintf(&sb, "Tokens: %d\n", totalTokens)
   248→	}
   249→
   250→	sb.WriteString("\n")
   251→
   252→	// Intent (use first line of prompts as fallback until AI summary is available)
   253→	intent := "(not generated)"
   254→	if result.Prompts != "" {
   255→		lines := strings.Split(result.Prompts, "\n")
   256→		if len(lines) > 0 && lines[0] != "" {
   257→			intent = lines[0]
   258→			if len(intent) > 80 {
   259→				intent = intent[:77] + "..."
   260→			}
   261→		}
   262→	}
   263→	fmt.Fprintf(&sb, "Intent: %s\n", intent)
   264→	sb.WriteString("Outcome: (not generated)\n")
   265→
   266→	// Verbose: add commit message, files, and prompts
   267→	if verbose || full {
   268→		// Commit message section (only if available)
   269→		if commitMessage != "" {
   270→			sb.WriteString("\n")
   271→			fmt.Fprintf(&sb, "Commit: %s\n", commitMessage)
   272→		}
   273→
   274→		sb.WriteString("\n")
   275→
   276→		// Files section
   277→		if len(meta.FilesTouched) > 0 {
   278→			fmt.Fprintf(&sb, "Files: (%d)\n", len(meta.FilesTouched))
   279→			for _, file := range meta.FilesTouched {
   280→				fmt.Fprintf(&sb, "  - %s\n", file)
   281→			}
   282→		} else {
   283→			sb.WriteString("Files: (none)\n")
   284→		}
   285→
   286→		sb.WriteString("\n")
   287→
   288→		// Prompts section
   289→		sb.WriteString("Prompts:\n")
   290→		if result.Prompts != "" {
   291→			sb.WriteString(result.Prompts)
   292→			sb.WriteString("\n")
   293→		} else {
   294→			sb.WriteString("  (none)\n")
   295→		}
   296→	}
   297→
   298→	// Full: add transcript
   299→	if full {
   300→		sb.WriteString("\n")
   301→		sb.WriteString("Transcript:\n")
   302→		if len(result.Transcript) > 0 {
   303→			sb.Write(result.Transcript)
   304→			sb.WriteString("\n")
   305→		} else {
   306→			sb.WriteString("  (none)\n")
   307→		}
   308→	}
   309→
   310→	return sb.String()
   311→}
