   313→// runExplainDefault explains the current session.
   314→func runExplainDefault(w io.Writer, noPager bool) error {
   315→	// Read current session
   316→	currentSessionID, err := paths.ReadCurrentSession()
   317→	if err != nil {
   318→		return fmt.Errorf("failed to read current session: %w", err)
   319→	}
   320→
   321→	if currentSessionID == "" {
   322→		return errors.New("no active session. Use --session or --commit to specify what to explain")
   323→	}
   324→
   325→	return runExplainSession(w, currentSessionID, noPager)
