   328→// runExplainSession explains a specific session.
   329→func runExplainSession(w io.Writer, sessionID string, noPager bool) error {
   330→	strat := GetStrategy()
   331→
   332→	// Get session details
   333→	session, err := strategy.GetSession(sessionID)
   334→	if err != nil {
   335→		if errors.Is(err, strategy.ErrNoSession) {
   336→			return fmt.Errorf("session not found: %s", sessionID)
   337→		}
   338→		return fmt.Errorf("failed to get session: %w", err)
   339→	}
   340→
   341→	// Get source ref (metadata branch + commit) for this session
   342→	sourceRef := strat.GetSessionMetadataRef(session.ID)
   343→
   344→	// Gather checkpoint details
   345→	checkpointDetails := gatherCheckpointDetails(strat, session)
   346→
   347→	// For strategies like shadow where active sessions may not have checkpoints,
   348→	// try to get the current session transcript directly
   349→	if len(checkpointDetails) == 0 && len(session.Checkpoints) == 0 {
   350→		checkpointDetails = gatherCurrentSessionDetails(strat, session)
   351→	}
   352→
   353→	// Format output
   354→	output := formatSessionInfo(session, sourceRef, checkpointDetails)
   355→
   356→	// Output with pager if appropriate
   357→	if noPager {
   358→		fmt.Fprint(w, output)
   359→	} else {
   360→		outputWithPager(w, output)
   361→	}
   362→
   363→	return nil
   364→}
