   366→// gatherCurrentSessionDetails attempts to get transcript info for sessions without checkpoints.
   367→// This handles strategies like shadow where active sessions may not have checkpoint commits.
   368→func gatherCurrentSessionDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   369→	// Try to get transcript via GetSessionContext which reads from metadata branch
   370→	// For shadow, we can read the transcript from the same location pattern
   371→	contextContent := strat.GetSessionContext(session.ID)
   372→	if contextContent == "" {
   373→		return nil
   374→	}
   375→
   376→	// Parse the context.md to extract the last prompt/summary
   377→	// Context.md typically has sections like "# Prompt\n...\n## Summary\n..."
   378→	detail := checkpointDetail{
   379→		Index:     1,
   380→		Timestamp: session.StartTime,
   381→		Message:   "Current session",
   382→	}
   383→
   384→	// Try to extract prompt and summary from context.md
   385→	lines := strings.Split(contextContent, "\n")
   386→	var inPrompt, inSummary bool
   387→	var promptLines, summaryLines []string
   388→
   389→	for _, line := range lines {
   390→		trimmed := strings.TrimSpace(line)
   391→		if strings.HasPrefix(trimmed, "# ") && strings.Contains(strings.ToLower(trimmed), "prompt") {
   392→			inPrompt = true
   393→			inSummary = false
   394→			continue
   395→		}
   396→		if strings.HasPrefix(trimmed, "## ") && strings.Contains(strings.ToLower(trimmed), "summary") {
   397→			inPrompt = false
   398→			inSummary = true
   399→			continue
   400→		}
   401→		if strings.HasPrefix(trimmed, "## ") || strings.HasPrefix(trimmed, "# ") {
   402→			inPrompt = false
   403→			inSummary = false
   404→			continue
   405→		}
   406→
   407→		if inPrompt {
   408→			promptLines = append(promptLines, line)
   409→		} else if inSummary {
   410→			summaryLines = append(summaryLines, line)
   411→		}
   412→	}
   413→
   414→	var inter interaction
   415→	if len(promptLines) > 0 {
   416→		inter.Prompt = strings.TrimSpace(strings.Join(promptLines, "\n"))
   417→	}
   418→	if len(summaryLines) > 0 {
   419→		inter.Responses = []string{strings.TrimSpace(strings.Join(summaryLines, "\n"))}
   420→	}
   421→
   422→	// If we couldn't parse structured content, show the raw context
   423→	if inter.Prompt == "" && len(inter.Responses) == 0 {
   424→		inter.Responses = []string{contextContent}
   425→	}
   426→
   427→	if inter.Prompt != "" || len(inter.Responses) > 0 {
   428→		detail.Interactions = []interaction{inter}
   429→	}
   430→
   431→	return []checkpointDetail{detail}
   432→}
