   434→// gatherCheckpointDetails extracts detailed information for each checkpoint.
   435→// Checkpoints come in newest-first order, but we number them oldest=1, newest=N.
   436→func gatherCheckpointDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   437→	details := make([]checkpointDetail, 0, len(session.Checkpoints))
   438→	total := len(session.Checkpoints)
   439→
   440→	for i, cp := range session.Checkpoints {
   441→		detail := checkpointDetail{
   442→			Index:            total - i, // Reverse numbering: oldest=1, newest=N
   443→			Timestamp:        cp.Timestamp,
   444→			IsTaskCheckpoint: cp.IsTaskCheckpoint,
   445→			Message:          cp.Message,
   446→		}
   447→
   448→		// Use checkpoint ID for display (truncate long IDs)
   449→		detail.ShortID = cp.CheckpointID
   450→		if len(detail.ShortID) > 12 {
   451→			detail.ShortID = detail.ShortID[:12]
   452→		}
   453→
   454→		// Try to get transcript for this checkpoint
   455→		transcriptContent, err := strat.GetCheckpointLog(cp)
   456→		if err == nil {
   457→			transcript, parseErr := parseTranscriptFromBytes(transcriptContent)
   458→			if parseErr == nil {
   459→				// Extract all prompt/response pairs from the transcript
   460→				pairs := ExtractAllPromptResponses(transcript)
   461→				for _, pair := range pairs {
   462→					detail.Interactions = append(detail.Interactions, interaction(pair))
   463→				}
   464→
   465→				// Aggregate all files for the checkpoint
   466→				fileSet := make(map[string]bool)
   467→				for _, pair := range pairs {
   468→					for _, f := range pair.Files {
   469→						if !fileSet[f] {
   470→							fileSet[f] = true
   471→							detail.Files = append(detail.Files, f)
   472→						}
   473→					}
   474→				}
   475→			}
   476→		}
   477→
   478→		details = append(details, detail)
   479→	}
   480→
   481→	return details
   482→}
