   484→// runExplainCommit explains a specific commit.
   485→func runExplainCommit(w io.Writer, commitRef string) error {
   486→	repo, err := openRepository()
   487→	if err != nil {
   488→		return fmt.Errorf("not a git repository: %w", err)
   489→	}
   490→
   491→	// Resolve the commit reference
   492→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
   493→	if err != nil {
   494→		return fmt.Errorf("commit not found: %s", commitRef)
   495→	}
   496→
   497→	commit, err := repo.CommitObject(*hash)
   498→	if err != nil {
   499→		return fmt.Errorf("failed to get commit: %w", err)
   500→	}
   501→
   502→	// Get files changed in this commit (diff from parent to current)
   503→	var files []string
   504→	commitTree, err := commit.Tree()
   505→	if err == nil && commit.NumParents() > 0 {
   506→		parent, parentErr := commit.Parent(0)
   507→		if parentErr == nil {
   508→			parentTree, treeErr := parent.Tree()
   509→			if treeErr == nil {
   510→				// Diff from parent to current commit to show what changed
   511→				changes, diffErr := parentTree.Diff(commitTree)
   512→				if diffErr == nil {
   513→					for _, change := range changes {
   514→						name := change.To.Name
   515→						if name == "" {
   516→							name = change.From.Name
   517→						}
   518→						files = append(files, name)
   519→					}
   520→				}
   521→			}
   522→		}
   523→	}
   524→
   525→	// Check for Entire metadata
   526→	metadataDir, hasMetadata := paths.ParseMetadataTrailer(commit.Message)
   527→	sessionID, hasSession := paths.ParseSessionTrailer(commit.Message)
   528→
   529→	// If no session trailer, try to extract from metadata path.
   530→	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
   531→	// by both the rewind and explain commands for parsing metadata paths.
   532→	if !hasSession && hasMetadata {
   533→		sessionID = extractSessionIDFromMetadata(metadataDir)
   534→		hasSession = sessionID != ""
   535→	}
   536→
   537→	// Build commit info
   538→	fullSHA := hash.String()
   539→	shortSHA := fullSHA
   540→	if len(fullSHA) >= 7 {
   541→		shortSHA = fullSHA[:7]
   542→	}
   543→
   544→	info := &commitInfo{
   545→		SHA:       fullSHA,
   546→		ShortSHA:  shortSHA,
   547→		Message:   strings.Split(commit.Message, "\n")[0], // First line only
   548→		Author:    commit.Author.Name,
   549→		Email:     commit.Author.Email,
   550→		Date:      commit.Author.When,
   551→		Files:     files,
   552→		HasEntire: hasMetadata || hasSession,
   553→		SessionID: sessionID,
   554→	}
   555→
   556→	// Format and output
   557→	output := formatCommitInfo(info)
   558→	fmt.Fprint(w, output)
   559→
   560→	return nil
   561→}
