   563→// formatSessionInfo formats session information for display.
   564→func formatSessionInfo(session *strategy.Session, sourceRef string, checkpoints []checkpointDetail) string {
   565→	var sb strings.Builder
   566→
   567→	// Session header
   568→	fmt.Fprintf(&sb, "Session: %s\n", session.ID)
   569→	fmt.Fprintf(&sb, "Strategy: %s\n", session.Strategy)
   570→
   571→	if !session.StartTime.IsZero() {
   572→		fmt.Fprintf(&sb, "Started: %s\n", session.StartTime.Format("2006-01-02 15:04:05"))
   573→	}
   574→
   575→	if sourceRef != "" {
   576→		fmt.Fprintf(&sb, "Source Ref: %s\n", sourceRef)
   577→	}
   578→
   579→	fmt.Fprintf(&sb, "Checkpoints: %d\n", len(checkpoints))
   580→
   581→	// Checkpoint details
   582→	for _, cp := range checkpoints {
   583→		sb.WriteString("\n")
   584→
   585→		// Checkpoint header
   586→		taskMarker := ""
   587→		if cp.IsTaskCheckpoint {
   588→			taskMarker = " [Task]"
   589→		}
   590→		fmt.Fprintf(&sb, "─── Checkpoint %d [%s] %s%s ───\n",
   591→			cp.Index, cp.ShortID, cp.Timestamp.Format("2006-01-02 15:04"), taskMarker)
   592→		sb.WriteString("\n")
   593→
   594→		// Display all interactions in this checkpoint
   595→		for i, inter := range cp.Interactions {
   596→			// For multiple interactions, add a sub-header
   597→			if len(cp.Interactions) > 1 {
   598→				fmt.Fprintf(&sb, "### Interaction %d\n\n", i+1)
   599→			}
   600→
   601→			// Prompt section
   602→			if inter.Prompt != "" {
   603→				sb.WriteString("## Prompt\n\n")
   604→				sb.WriteString(inter.Prompt)
   605→				sb.WriteString("\n\n")
   606→			}
   607→
   608→			// Response section
   609→			if len(inter.Responses) > 0 {
   610→				sb.WriteString("## Responses\n\n")
   611→				sb.WriteString(strings.Join(inter.Responses, "\n\n"))
