   645→// formatCommitInfo formats commit information for display.
   646→func formatCommitInfo(info *commitInfo) string {
   647→	var sb strings.Builder
   648→
   649→	fmt.Fprintf(&sb, "Commit: %s (%s)\n", info.SHA, info.ShortSHA)
   650→	fmt.Fprintf(&sb, "Date: %s\n", info.Date.Format("2006-01-02 15:04:05"))
   651→
   652→	if info.HasEntire && info.SessionID != "" {
   653→		fmt.Fprintf(&sb, "Session: %s\n", info.SessionID)
   654→	}
   655→
   656→	sb.WriteString("\n")
   657→
   658→	// Message
   659→	sb.WriteString("Message:\n")
   660→	fmt.Fprintf(&sb, "  %s\n", info.Message)
   661→	sb.WriteString("\n")
   662→
   663→	// Files modified
   664→	if len(info.Files) > 0 {
   665→		fmt.Fprintf(&sb, "Files Modified (%d):\n", len(info.Files))
   666→		for _, file := range info.Files {
   667→			fmt.Fprintf(&sb, "  - %s\n", file)
   668→		}
   669→		sb.WriteString("\n")
   670→	}
   671→
   672→	// Note for non-Entire commits
   673→	if !info.HasEntire {
   674→		sb.WriteString("Note: No Entire session data available for this commit.\n")
   675→	}
   676→
   677→	return sb.String()
   678→}
