   680→// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
   681→func outputWithPager(w io.Writer, content string) {
   682→	// Check if we're writing to stdout and it's a terminal
   683→	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
   684→		// Get terminal height
   685→		_, height, err := term.GetSize(int(f.Fd()))
   686→		if err != nil {
   687→			height = 24 // Default fallback
   688→		}
   689→
   690→		// Count lines in content
   691→		lineCount := strings.Count(content, "\n")
   692→
   693→		// Use pager if content exceeds terminal height
   694→		if lineCount > height-2 {
   695→			pager := os.Getenv("PAGER")
   696→			if pager == "" {
   697→				pager = "less"
   698→			}
   699→
   700→			cmd := exec.CommandContext(context.Background(), pager) //nolint:gosec // pager from env is expected
   701→			cmd.Stdin = strings.NewReader(content)
   702→			cmd.Stdout = f
   703→			cmd.Stderr = os.Stderr
   704→
   705→			if err := cmd.Run(); err != nil {
   706→				// Fallback to direct output if pager fails
   707→				fmt.Fprint(w, content)
   708→			}
   709→			return
   710→		}
   711→	}
   712→
   713→	// Direct output for non-terminal or short content
   714→	fmt.Fprint(w, content)
   715→}
