    16→// Session represents a Claude Code session with its checkpoints.
    17→// A session is created when a user runs `claude` and tracks all changes
    18→// made during that interaction.
    19→type Session struct {
    20→	// ID is the unique session identifier (e.g., "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e")
    21→	ID string
    22→
    23→	// Description is a human-readable summary of the session
    24→	// (typically the first prompt or derived from commit messages)
    25→	Description string
    26→
    27→	// Strategy is the name of the strategy that created this session
    28→	Strategy string
    29→
    30→	// StartTime is when the session was started
    31→	StartTime time.Time
    32→
    33→	// Checkpoints is the list of save points within this session
    34→	Checkpoints []Checkpoint
    35→}
    36→
    37→// Checkpoint represents a save point within a session.
    38→// Checkpoints can be either session-level (on Stop) or task-level (on subagent completion).
    39→type Checkpoint struct {
    40→	// CheckpointID is the stable 12-hex-char identifier for this checkpoint.
    41→	// Used to look up metadata at <id[:2]>/<id[2:]>/ on entire/sessions branch.
    42→	CheckpointID string
    43→
    44→	// Message is the commit message or checkpoint description
    45→	Message string
    46→
    47→	// Timestamp is when this checkpoint was created
    48→	Timestamp time.Time
    49→
    50→	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
    51→	IsTaskCheckpoint bool
    52→
    53→	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
    54→	ToolUseID string
