    82→// ListSessions returns all sessions from the entire/sessions branch,
    83→// plus any additional sessions from strategies implementing SessionSource.
    84→// It automatically discovers all registered strategies and merges their sessions.
    85→func ListSessions() ([]Session, error) {
    86→	repo, err := OpenRepository()
    87→	if err != nil {
    88→		return nil, fmt.Errorf("failed to open git repository: %w", err)
    89→	}
    90→
    91→	// Get checkpoints from the entire/sessions branch
    92→	checkpoints, err := ListCheckpoints()
    93→	if err != nil {
    94→		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
    95→	}
    96→
    97→	// Group checkpoints by session ID
    98→	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
    99→	sessionMap := make(map[string]*Session)
   100→	for _, cp := range checkpoints {
   101→		// Determine which session IDs this checkpoint belongs to
   102→		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
   103→		sessionIDs := cp.SessionIDs
   104→		if len(sessionIDs) == 0 {
   105→			sessionIDs = []string{cp.SessionID}
   106→		}
   107→
   108→		for _, sessionID := range sessionIDs {
   109→			if sessionID == "" {
   110→				continue
   111→			}
   112→
   113→			if existing, ok := sessionMap[sessionID]; ok {
   114→				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
   115→					CheckpointID:     cp.CheckpointID,
   116→					Message:          "Checkpoint: " + cp.CheckpointID,
   117→					Timestamp:        cp.CreatedAt,
   118→					IsTaskCheckpoint: cp.IsTask,
   119→					ToolUseID:        cp.ToolUseID,
   120→				})
   121→			} else {
   122→				// Get description from the checkpoint tree
   123→				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)
   124→
   125→				sessionMap[sessionID] = &Session{
   126→					ID:          sessionID,
   127→					Description: description,
   128→					Strategy:    "", // Will be set from metadata if available
   129→					StartTime:   cp.CreatedAt,
   130→					Checkpoints: []Checkpoint{{
   131→						CheckpointID:     cp.CheckpointID,
   132→						Message:          "Checkpoint: " + cp.CheckpointID,
   133→						Timestamp:        cp.CreatedAt,
   134→						IsTaskCheckpoint: cp.IsTask,
   135→						ToolUseID:        cp.ToolUseID,
   136→					}},
   137→				}
   138→			}
   139→		}
   140→	}
   141→
   142→	// Check all registered strategies for additional sessions
   143→	for _, name := range List() {
   144→		strat, stratErr := Get(name)
   145→		if stratErr != nil {
   146→			continue
   147→		}
   148→		source, ok := strat.(SessionSource)
   149→		if !ok {
   150→			continue
   151→		}
   152→		additionalSessions, addErr := source.GetAdditionalSessions()
   153→		if addErr != nil {
   154→			continue // Skip strategies that fail to provide additional sessions
   155→		}
   156→		for _, addSession := range additionalSessions {
   157→			if addSession == nil {
   158→				continue
   159→			}
   160→			if existing, ok := sessionMap[addSession.ID]; ok {
   161→				// Merge checkpoints - deduplicate by CheckpointID
   162→				existingCPIDs := make(map[string]bool)
   163→				for _, cp := range existing.Checkpoints {
   164→					existingCPIDs[cp.CheckpointID] = true
   165→				}
   166→				for _, cp := range addSession.Checkpoints {
   167→					if !existingCPIDs[cp.CheckpointID] {
   168→						existing.Checkpoints = append(existing.Checkpoints, cp)
   169→					}
   170→				}
   171→				// Update start time if additional session is older
   172→				if addSession.StartTime.Before(existing.StartTime) {
   173→					existing.StartTime = addSession.StartTime
   174→				}
   175→				// Use description from additional source if existing is empty
   176→				if existing.Description == "" || existing.Description == NoDescription {
   177→					existing.Description = addSession.Description
   178→				}
   179→			} else {
   180→				// New session from additional source
   181→				sessionMap[addSession.ID] = addSession
   182→			}
   183→		}
   184→	}
   185→
   186→	// Convert map to slice
   187→	sessions := make([]Session, 0, len(sessionMap))
   188→	for _, session := range sessionMap {
   189→		// Sort checkpoints within each session by timestamp (most recent first)
   190→		sort.Slice(session.Checkpoints, func(i, j int) bool {
   191→			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
   192→		})
   193→		sessions = append(sessions, *session)
   194→	}
   195→
   196→	// Sort sessions by start time (most recent first)
   197→	sort.Slice(sessions, func(i, j int) bool {
   198→		return sessions[i].StartTime.After(sessions[j].StartTime)
   199→	})
   200→
   201→	return sessions, nil
   202→}
