   204→// GetSession finds a session by ID (supports prefix matching).
   205→// Returns ErrNoSession if no matching session is found.
   206→func GetSession(sessionID string) (*Session, error) {
   207→	sessions, err := ListSessions()
   208→	if err != nil {
   209→		return nil, err
   210→	}
   211→	return findSessionByID(sessions, sessionID)
   212→}
   213→
   214→// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/sessions branch.
   215→func getDescriptionForCheckpoint(repo *git.Repository, checkpointID string) string {
   216→	tree, err := GetMetadataBranchTree(repo)
   217→	if err != nil {
   218→		return NoDescription
   219→	}
   220→
   221→	checkpointPath := paths.CheckpointPath(checkpointID)
   222→	return getSessionDescriptionFromTree(tree, checkpointPath)
   223→}
   224→
   225→// findSessionByID finds a session by exact ID or prefix match.
   226→func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
   227→	for _, session := range sessions {
   228→		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
   229→			return &session, nil
   230→		}
   231→	}
   232→	return nil, ErrNoSession
   233→}
